        html += '<p style="margin:3px 0 0;font-size:13px;color:#576A72;">' + (cfg.storeSubtitle || 'Artículos de Limpieza, Perfumería, Bazar y Anexos • Mayor y Menor') + ' • ' + (cfg.address || 'PRINGLES 467, SAMPACHO') + '</p></div>';
